    @Test
    public void testAcceptJsonFormatVisitor_AlwaysEntersTrueBranch() throws JsonMappingException {
        // Given: A NumberSerializer for Integer
        NumberSerializer serializer = new NumberSerializer<>(Integer.class);

        // When: Calling acceptJsonFormatVisitor
        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // Then: Since 'if (true)' is hardcoded, it should call visitIntFormat
        // Based on Jackson's internal structure, visitIntFormat calls visitor.expectNumberFormat
        // with the BIG_INTEGER type hint.
        verify(visitor).expectNumberFormat(typeHint);
    }

